<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\Tenant\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\Tenant\Domain\ValueObject\TenantRootVO;

trait TenantRootAttributeHolder
{
    protected TenantRootVO|bool|null $root = null;
    protected bool $rootAssigned = false;

    public function getRootOrCurrent(?TenantRootVO $root): ?TenantRootVO
    {
        return $this->rootAssigned ? ($this->root === null ? null : TenantRootVO::from($this->root)) : $root;
    }
    public function rootTryBuildInitial(ConstraintFailList $error): ?TenantRootVO
    {
        return  TenantRootVO::tryFrom($this->rootAssigned ? $this->root : false, $error);
    }
    public function root(TenantRootVO|bool|null $root): static
    {
        $this->root = $root;
        $this->rootAssigned = true;
        return $this;
    }
    public function isRoot(): ?bool
    {
        return $this->root instanceof TenantRootVO ? $this->root->value() : $this->root;
    }
    public function isRootAssigned(): bool
    {
        return $this->rootAssigned;
    }
    public function writeRootTo(mixed $att): void
    {
        if ($this->rootAssigned) {
            $att->root($this->root);
        }
    }
    public function readRootFrom(mixed $att): void
    {
        if ($att->isRootAssigned()) {
            $root = $att->isRoot();
            $this->root($root);
        }
    }
    public function unsetRoot(): static
    {
        $this->rootAssigned = false;
        return $this;
    }
    protected function withDefaultRoot(): void
    {
        if ($this->root === null) {
            $this->root = false;
        }
    }
    protected function withAssertedRootRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->rootAssigned = $this->rootAssigned) {
            $value->root = TenantRootVO::tryFrom($this->root, $errorsList);
        }
    }
}
